package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaThDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("ซุบบูฮุน กุดดุส (รุกู และ สุจูด)", "(อัลเลาะห์) เป็นที่สรรเสริญสูงสุด บริสุทธิ์ที่สุด พระเจ้าแห่งมลาอิกะฮ์และพระวิญญาณ (ญิบรีล)", "ในรูกุและซูจูด", "พระศาสดา ﷺ ท่องสิ่งนี้ในรุกูและซูจูด"),
        "dua_sujood_dhanbi_kullah" to DuaText("อินซูจูด: โปรดยกโทษบาปทั้งหมดของฉัน", "โอ้อัลลอฮ์ โปรดอภัยโทษบาปทั้งหมดของฉัน ทั้งบาปเล็กและใหญ่ บาปแรกและบาปสุดท้าย บาปที่เปิดกว้างและซ่อนเร้น", "อินซูจูด.", "การสุญูดเป็นสถานที่ที่ดุอาถูกตอบ"),
        "dua_sujood_ridaka" to DuaText("ที่ลี้ภัยในความสุขของคุณ", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อความพอพระทัยของพระองค์ให้พ้นจากความโกรธของพระองค์ ในการอภัยโทษจากการลงโทษของพระองค์ และฉันขอความคุ้มครองจากพระองค์จากพระองค์ ข้าพระองค์ไม่สามารถสรรเสริญพระองค์ได้อย่างเต็มที่ คุณเป็นเหมือนที่คุณสรรเสริญตัวเอง", "ในซูจูด — ไอชา (RA) ได้ยินพระศาสดา ﷺ พูดเช่นนี้", "ดุอาซูจูดของท่านศาสดา ﷺ"),
        "dua_tashahhud" to DuaText("Tashahhud (อัต-ตะฮิยัท)", "การสักการะทั้งทางวาจา ทางร่างกาย และทางการเงินทั้งหมดเป็นไปเพื่ออัลลอฮฺ สันติสุขจงมีแด่ท่าน ข้าแต่พระศาสดา และความเมตตาของอัลลอฮ์และพระพรของพระองค์ สันติภาพจงมีแด่เราและแก่บ่าวผู้ชอบธรรมของอัลลอฮ์ ฉันเป็นพยานว่าไม่มีผู้ใดมีสิทธิที่จะได้รับการสักการะนอกจากอัลลอฮ์ และฉันเป็นพยานว่ามูฮัมหมัด ﷺ เป็นผู้รับใช้และศาสนทูตของพระองค์", "ในทุกการประชุม — บรรยายโดยอับดุลลอฮ์ อิบนุ มัสอูด (RA) (บทปฏิบัติของฮานาฟี)", "ศาสดา ﷺ สอนเหมือนซูเราะห์ของอัลกุรอาน"),
        "dua_sajdah_tilawah" to DuaText("Sajdah ของการบรรยาย", "ใบหน้าของฉันกราบลงต่อพระองค์ผู้ทรงสร้างมันและนำการได้ยินและการมองเห็นออกมาด้วยพลังและอำนาจของพระองค์", "ในการสุญูดของการสวด", "พระศาสดา ﷺ กล่าวสิ่งนี้ในการสุญูดการอ่านในเวลากลางคืน"),
        "dua_after_witr" to DuaText("หลังวิทย์", "ถวายพระเกียรติแด่พระมหากษัตริย์ผู้ทรงบริสุทธิ์ที่สุด", "สามครั้งหลังสลามวิเตร ให้ขึ้นเสียงเป็นครั้งที่สาม", "พระศาสดา ﷺ กล่าวสิ่งนี้หลังจากวิทร"),
        "dua_tahajjud_nur" to DuaText("คำอธิษฐานเปิดตะฮัจญุด", "โอ้อัลลอฮ์ การสรรเสริญเป็นของพระองค์ คุณคือผู้ค้ำจุนชั้นฟ้าทั้งหลาย แผ่นดิน และทุกสิ่งที่อยู่ภายในพวกเขา การสรรเสริญเป็นของพระองค์ คุณคือแสงสว่างแห่งชั้นฟ้าทั้งหลาย แผ่นดิน และทุกสิ่งที่อยู่ภายในนั้น การสรรเสริญเป็นของพระองค์ คุณคือความจริง คำสัญญาของคุณเป็นจริง การพบกับคุณเป็นจริง พระวจนะของคุณเป็นจริง สวรรค์เป็นจริง นรกเป็นจริง ผู้เผยพระวจนะเป็นจริง มูฮัมหมัด ﷺ เป็นจริง และวันอวสานเป็นจริง", "เมื่อเริ่มละหมาดตอนกลางคืน (ตะฮัจญุด) (ท่อนเปิดดุอา)", "พระศาสดา ﷺ ท่องสิ่งนี้เกี่ยวกับการลุกขึ้นเพื่อตะฮัจญุด (ดุอาเต็มอยู่ในอัลบุคอรี)"),
        "dua_rabba_jibrail" to DuaText("ขอทรงนำทางข้าพระองค์ในเรื่องที่ถกเถียงกัน", "โอ้อัลลอฮ์ พระเจ้าแห่งญิบรีล มิคาอิลและอิสรอฟีล ผู้ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดิน ผู้ทรงรอบรู้สิ่งเร้นลับและสิ่งที่มองเห็น! พระองค์จะทรงตัดสินระหว่างผู้รับใช้ของพระองค์ในสิ่งที่พวกเขาเคยขัดแย้งกัน โปรดชี้ทางให้ฉันด้วยการอนุมัติของพระองค์ไปสู่ความจริงในสิ่งที่ขัดแย้งกัน แท้จริงพระองค์ทรงแนะนำผู้ที่พระองค์ทรงประสงค์ให้ไปสู่ทางอันเที่ยงตรง", "ที่จุดเริ่มต้นของตะฮัจญุด — เพื่อนำทางสู่ความจริงท่ามกลางความขัดแย้ง", "ศาสดา ﷺ เริ่มสวดมนต์ตอนกลางคืนด้วยดุอานี้"),
        "dua_going_to_mosque_nur" to DuaText("การไปมัสยิด (ดุอาแห่งแสงสว่าง)", "โอ้อัลลอฮ์ โปรดประทานแสงสว่างในหัวใจของฉัน แสงสว่างในดวงตาของฉัน แสงสว่างในหูของฉัน แสงสว่างทางด้านขวาของฉัน แสงสว่างด้านซ้ายของฉัน แสงสว่างเหนือฉัน แสงสว่างด้านล่างของฉัน แสงสว่างข้างหน้าฉัน แสงสว่างข้างหลังฉัน และจงให้แสงสว่างแก่ฉันด้วย", "ขณะไปมัสยิดเพื่อฟัจร์", "พระศาสดา ﷺ ท่องสิ่งนี้เมื่อออกไปสวดมนต์"),
        "dua_waswasa_salah" to DuaText("วะสวาสะระหว่างละหมาด (คินซาบ)", "ฉันขอความคุ้มครองต่ออัลลอฮ์ให้พ้นจากชัยฏอนผู้ถูกสาปแช่ง", "เมื่อมีเสียงกระซิบของซาตานมาขณะสวดมนต์ ให้ขอความคุ้มครอง แล้วบ้วนน้ำลายไปทางซ้ายเบา ๆ สามครั้ง", "อุษมาน บิน อาบีล ดังที่ (RA) ได้กระทำสิ่งนี้ และเสียงกระซิบก็หายไป"),
        "dua_alimal_ghayb" to DuaText("ผู้รู้แจ้งในสิ่งเร้นลับ", "โอ้อัลลอฮ์ ผู้ทรงรอบรู้สิ่งเร้นลับและสิ่งที่มองเห็น ผู้สร้างชั้นฟ้าทั้งหลายและแผ่นดิน พระเจ้าและผู้ทรงอำนาจเหนือทุกสิ่ง! ข้าพเจ้าเป็นพยานว่าไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วร้ายในตัวฉันเอง และจากความชั่วร้ายของชัยฏอนและชิริกของเขา", "เช้า เย็น และก่อนนอน ท่านศาสดา ﷺ สอนอบูบักร์ (RA)", "ป้องกันความชั่วร้ายของตนเองและชัยฏอน"),
        "dua_fitratil_islam" to DuaText("เมื่อฟิตเราะห์ของศาสนาอิสลาม", "เราได้เข้าสู่ยามเช้าแล้วกับฟิตเราะห์ของศาสนาอิสลาม กับถ้อยคำแห่งความจริงใจ กับศาสนาของศาสดามุฮัมมัดของเรา ﷺ และบนเส้นทางของอิบรอฮีม (AS) บิดาของเรา ผู้มีความเที่ยงธรรมและเป็นมุสลิม และไม่ได้อยู่ในกลุ่มผู้นับถือพระเจ้า", "ในตอนเช้า.", "ปลุกศรัทธาใหม่ทุกเช้า"),
        "dua_amsayna_fitrah" to DuaText("ยามเย็นเมื่อฟิตเราะฮฺของศาสนาอิสลาม", "เราได้เข้าสู่เวลาเย็นด้วยฟิตเราะห์ของศาสนาอิสลาม กับถ้อยคำแห่งความจริงใจ กับศาสนาของศาสดามุฮัมมัดของเรา ﷺ และบนเส้นทางของอิบรอฮีม (AS) บิดาของเรา ผู้มีความเที่ยงธรรมและเป็นมุสลิม และไม่ได้อยู่ในกลุ่มผู้นับถือพระเจ้า", "ในตอนเย็น.", "ปลุกศรัทธาใหม่ทุกเย็น"),
        "dua_tahleel_10_fajr" to DuaText("สิบตะห์ลีลหลังฟัยริและมักริบ", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ พระองค์ทรงให้ชีวิตและทำให้เกิดความตาย และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง", "สิบครั้งหลังการฟัจรฺ (และมักริบ) ก่อนที่จะลุกจากการนั่งหรือพูด", "ความดีสิบประการ ลบบาปสิบประการ ยกระดับขึ้นสิบอันดับ และคุ้มครองชัยฏอนตลอดทั้งวัน"),
        "dua_la_hawla_kanz" to DuaText("สมบัติของ Jannah", "ไม่มีอำนาจและไม่มีอำนาจใด ๆ เว้นแต่กับอัลลอฮ์", "บ่อยครั้งตลอดเวลา", "มันเป็นหนึ่งในสมบัติของสวรรค์"),
        "dua_four_beloved_words" to DuaText("สี่คำที่รักที่สุด", "มหาบริสุทธิ์แห่งอัลลอฮ์ การสรรเสริญทั้งมวลเป็นของอัลลอฮ์ ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ และอัลลอฮ์นั้นยิ่งใหญ่ที่สุด", "คำพูดอันเป็นที่รักยิ่งของอัลลอฮฺ", "พวกเขาเป็นที่รักต่อศาสดาพยากรณ์ ﷺ มากกว่าทุกสิ่งที่ดวงอาทิตย์ขึ้น"),
        "dua_two_light_words" to DuaText("สองคำสว่างบนลิ้น", "มหาบริสุทธิ์แห่งอัลลอฮ์และการสรรเสริญทั้งมวลเป็นของพระองค์ มหาบริสุทธิ์แห่งอัลลอฮ์ผู้ทรงยิ่งใหญ่", "เบาบนลิ้น หนักบนตาชั่ง", "เป็นที่รักของพระผู้ทรงกรุณาปรานี เบาลิ้นและหนักบนตาชั่ง (สุนัตสุดท้ายของอัลบุคอรี)"),
        "dua_ya_dhal_jalal" to DuaText("ยา ดัล-จาลาลี วัล-อิกราม", "ข้าแต่ผู้ครอบครองพระบาทสมเด็จพระเจ้าอยู่หัวและเกียรติยศ!", "ยึดมั่นในดุอา — คำแนะนำของศาสดาพยากรณ์ ﷺ", "พระศาสดา ﷺ กล่าวว่า: ยึดมั่นใน 'ยา Dhal-Jalali wal-Ikram'"),
        "dua_sleep_wadatu_janbi" to DuaText("ในนามของคุณฉันนอนลง", "ข้าแต่พระเจ้า ข้าพระองค์นอนตะแคงและลุกขึ้นในพระนามของพระองค์ หากพระองค์ทรงรับจิตวิญญาณของฉัน โปรดเมตตามัน และหากพระองค์ทรงปล่อยมัน จงปกป้องมัน เช่นเดียวกับที่พระองค์ทรงปกป้องผู้รับใช้ที่ชอบธรรมของพระองค์", "หลังจากปัดฝุ่นเตียงและนอนราบแล้ว", "การฝากวิญญาณไว้กับอัลลอฮ์ก่อนนอน"),
        "dua_sleep_khalaqta_nafsi" to DuaText("คุณสร้างจิตวิญญาณของฉัน", "โอ้อัลลอฮ์ พระองค์ทรงสร้างจิตวิญญาณของฉัน และพระองค์จะทรงรับมัน ความตายและชีวิตของมันเป็นของคุณ ถ้าคุณทำให้มันมีชีวิตอยู่ จงปกป้องมัน และถ้าคุณทำให้มันตาย ก็จงให้อภัยมัน โอ้อัลลอฮ์ ฉันขอความอยู่ดีมีสุขจากพระองค์", "ก่อนนอน — รายงานโดย อิบนุ อุมัร (RA)", "ศาสดาพยากรณ์ ﷺ สอนให้พูดสิ่งนี้ก่อนนอน"),
        "dua_sleep_atamana" to DuaText("ขอบคุณก่อนนอน", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ผู้ทรงเลี้ยงดูเรา ให้เราดื่ม ประทานเพียงพอแก่เรา และประทานที่พักพิงแก่เรา มีสักกี่คนที่ไม่มีใครพอเลี้ยงหรือให้ที่พักพิงได้", "เมื่อเข้านอน.", "พระศาสดา ﷺ กล่าวเช่นนี้เมื่อเข้านอน"),
        "dua_sleep_rabbas_samawat" to DuaText("พระเจ้าแห่งสวรรค์ - ชำระหนี้ของเรา", "โอ้อัลลอฮ์ พระเจ้าแห่งชั้นฟ้าทั้งหลาย แผ่นดินและบัลลังก์อันยิ่งใหญ่ พระเจ้าของเราและพระเจ้าแห่งทุกสิ่ง ผู้แยกเมล็ดพืชและอินทผลัม ผู้เปิดเผยโตราห์ อินญีล และฟุรกอน! ข้าพระองค์ขอความคุ้มครองต่อพระองค์ให้พ้นจากความชั่วร้ายของทุกสิ่งที่พระองค์ทรงยึดไว้ โอ้อัลลอฮ์ พระองค์เป็นปฐม ไม่มีสิ่งใดอยู่เบื้องหน้าพระองค์ คุณคือคนสุดท้าย ไม่มีอะไรหลังจากคุณ พระองค์ทรงเป็นที่ประจักษ์ ไม่มีอะไรอยู่เหนือพระองค์ คุณคือผู้ซ่อนเร้น ไม่มีอะไรซ่อนเร้นจากคุณ ชำระหนี้แทนเราและปลดปล่อยเราจากความยากจน", "ก่อนนอนให้นอนตะแคงขวา — สอนแก่ฟาติมะห์ (RA)", "ดุอาอ์เพื่อปลดหนี้และความยากลำบาก"),
        "dua_sleep_fear" to DuaText("ความกลัวหรือความไม่สบายใจในการนอนหลับ", "ฉันขอความคุ้มครองต่อพระวจนะอันสมบูรณ์แบบของอัลลอฮ์ ให้พ้นจากความโกรธและการลงโทษของพระองค์ จากความชั่วร้ายของปวงบ่าวของพระองค์ และจากเสียงกระซิบของพวกมารร้าย และจากการที่พวกเขามาหาฉัน", "เมื่อรู้สึกกลัวหรือรู้สึกไม่สบายใจในขณะนอนหลับ", "การทำเช่นนั้นสิ่งนั้นจะไม่เป็นอันตรายต่อเขา"),
        "dua_waking_afani" to DuaText("ตื่น: พระองค์ทรงฟื้นฟูจิตวิญญาณของฉัน", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ผู้ทรงประทานความเป็นอยู่ที่ดีแก่ร่างกายของฉัน และคืนจิตวิญญาณของฉันให้ฉัน และอนุญาตให้ฉันรำลึกถึงพระองค์", "เมื่อตื่นนอน.", "ขอบคุณเช้าวันใหม่"),
        "dua_allahu_rabbi" to DuaText("อัลลอฮฺ อัลลอฮฺคือพระเจ้าของฉัน", "อัลลอฮฺ อัลลอฮฺคือพระเจ้าของฉัน ฉันไม่เชื่อมโยงสิ่งใดกับพระองค์", "ในความโศกเศร้าหรือความทุกข์ — พระศาสดา ﷺ สอนเรื่องนี้กับอัสมา บินติ อุมัยส (RA)", "ยึดถือหลักธรรมในยามทุกข์ยาก"),
        "dua_rahmataka_arju" to DuaText("ความเมตตาของคุณที่ฉันหวังไว้", "โอ้ อัลลอฮ์ เป็นความเมตตาของพระองค์ที่ฉันหวัง ดังนั้นอย่าปล่อยฉันไว้กับตัวเองแม้แต่ชั่วพริบตา และจงจัดการกิจการของฉันให้เรียบร้อย ไม่มีพระเจ้าอื่นใดนอกจากพระองค์", "ดุอาอ์ของผู้อยู่ในความทุกข์ (ดาวัท อัล-มักรุบ)", "พระศาสดา ﷺ เรียกมันว่าดุอาของผู้ที่มีความทุกข์"),
        "dua_against_enemy_ahzab" to DuaText("ต่อต้านกองทัพของศัตรู", "โอ้อัลลอฮ์ ผู้เปิดเผยคัมภีร์ รวดเร็วในการชำระบัญชี! เอาชนะสหพันธ์ โอ้อัลลอฮ์ โปรดเอาชนะพวกเขาและเขย่าพวกเขา", "ต่อต้านศัตรู - dua ของ Battle of the Confederates", "ﷺ ดุอาอ์ของท่านศาสดาต่อศัตรู"),
        "dua_anta_adudi" to DuaText("คุณคือกำลังใจของฉัน", "โอ้อัลลอฮ์ พระองค์ทรงเป็นผู้สนับสนุนและผู้ช่วยเหลือของฉัน โดยคุณฉันวางแผน โดยคุณฉันก้าวหน้า และโดยคุณฉันต่อสู้", "ก่อนการแข่งขันหรือความท้าทายครั้งสำคัญ", "พระศาสดา ﷺ กล่าวสิ่งนี้ในการต่อสู้"),
        "dua_ikfinihim" to DuaText("พอฉันต่อสู้กับพวกเขา", "โอ้อัลลอฮ์ โปรดให้ฉันต่อสู้กับพวกเขาตามที่พระองค์ประสงค์เถิด", "ต่อต้านความชั่วร้ายของผู้กดขี่ - ดุอาของเด็กชายในเรื่อง The People of the Ditch", "อัลลอฮ์ทรงช่วยเด็กให้พ้นจากผู้กดขี่"),
        "dua_qadarullah" to DuaText("เมื่อมีสิ่งเลวร้ายเกิดขึ้น", "มันเป็นคำสั่งของอัลลอฮ์ และพระองค์ทรงกระทำสิ่งที่พระองค์ทรงประสงค์", "เมื่อมีสิ่งไม่พึงประสงค์เกิดขึ้น แทนที่จะพูดว่า 'if only'", "'ถ้าเพียง' เปิดประตูสู่ชัยฏอน"),
        "dua_ala_kulli_hal" to DuaText("สรรเสริญในทุกสถานการณ์", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ในทุกสถานการณ์", "เมื่อมีสิ่งไม่ชอบมาพากลเกิดขึ้น", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อเผชิญกับสิ่งที่เขาไม่ชอบ"),
        "dua_dogs_barking" to DuaText("ได้ยินเสียงสุนัขเห่าตอนกลางคืน", "ฉันขอความคุ้มครองต่ออัลลอฮ์ให้พ้นจากชัยฏอนผู้ถูกสาปแช่ง", "เมื่อได้ยินเสียงสุนัขเห่าหรือเสียงลาร้องในเวลากลางคืน", "พวกเขาเห็นสิ่งที่คุณไม่เห็น"),
        "dua_leaving_home_adilla" to DuaText("ที่ลี้ภัยจากการหลงทาง", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ เกรงว่าฉันจะหลงทางหรือถูกชักพาให้หลงทาง เกรงว่าฉันจะพลาดหรือถูกทำให้ลื่น เกรงว่าฉันจะกระทำผิดหรือถูกอธรรม เกรงว่าฉันจะประพฤติตนโง่เขลา หรือถูกปฏิบัติอย่างโง่เขลา", "เมื่อออกจากบ้าน — รายงานโดย อุมม์ ซาลามะห์ (RA).", "ศาสดา ﷺ ท่องสิ่งนี้ทุกครั้งที่เขาออกจากบ้าน"),
        "dua_ascending_descending" to DuaText("ขึ้นและลง", "อัลลอฮฺคือผู้ทรงยิ่งใหญ่ (เมื่อเสด็จขึ้นไป) - มหาบริสุทธิ์แด่อัลลอฮ์ (เมื่อเสด็จลงมา)", "ในการเดินทาง ให้พูดว่า 'อัลลอฮ์ อัคบัร' เมื่อขึ้นไป และ 'ซุบฮานัลลอฮ์' เมื่อลงมา", "ข้อปฏิบัติของสหาย (RA) ขณะเดินทาง"),
        "dua_traveller_sahar" to DuaText("Dua ของนักเดินทางก่อนรุ่งสาง", "ผู้ฟังได้ยิน (และส่งต่อ) การสรรเสริญของเราต่ออัลลอฮ์และความโปรดปรานอันดีของพระองค์ที่มีต่อเรา พระเจ้าของเรา โปรดติดตามพวกเราไปและโปรดประทานความโปรดปรานแก่พวกเราด้วย (ฉันกล่าวสิ่งนี้) ขอความคุ้มครองจากอัลลอฮ์ให้พ้นจากไฟนรก", "ในการเดินทางก่อนรุ่งสาง", "ศาสดา ﷺ กล่าวสิ่งนี้ก่อนรุ่งสางเมื่อเดินทาง"),
        "dua_zawwadakallah" to DuaText("ถึงนักเดินทาง: ขออัลลอฮ์ทรงประทานการตักวา", "ขออัลลอฮ์ประทานตักวาแก่คุณสำหรับการเดินทางของคุณ ยกโทษบาปของคุณ และทำให้ความดีเป็นเรื่องง่ายสำหรับคุณไม่ว่าคุณจะอยู่ที่ไหน", "เมื่อกล่าวคำอำลากับนักเดินทาง", "พระศาสดา ﷺ มอบดุอานี้แก่ผู้ที่ออกเดินทาง"),
        "dua_traveller_to_resident" to DuaText("นักเดินทางสู่ผู้อยู่ข้างหลัง", "ฉันขอมอบความไว้วางใจต่ออัลลอฮ์แก่พระองค์ ผู้ซึ่งความไว้วางใจไม่เคยสูญหาย", "นักเดินทางกล่าวเมื่ออำลาครอบครัว", "มอบความปลอดภัยของครอบครัวให้กับอัลลอฮ."),
        "dua_entering_village" to DuaText("เข้าสู่เมืองหรือหมู่บ้าน", "โอ้ อัลลอฮฺ พระเจ้าแห่งชั้นฟ้าทั้งเจ็ดและทุกสิ่งที่พวกเขาบังเกิด พระเจ้าแห่งแผ่นดินทั้งเจ็ดและสิ่งที่พวกเขาบรรทุก พระเจ้าแห่งมารร้ายและทุกสิ่งที่พวกเขาหลงทาง พระเจ้าแห่งสายลมและทุกสิ่งที่พวกมันกระจัดกระจาย! เราขอความคุ้มครองจากพระองค์สำหรับความดีของเมืองนี้และความดีของประชาชนในเมืองนี้ และเราขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วของมัน ความชั่วของชาวเมืองนี้ และความชั่วของสิ่งที่อยู่ในนั้น", "ก่อนเข้าเมืองหรือเมือง", "พระศาสดา ﷺ ท่องสิ่งนี้ทุกครั้งที่เขาต้องการเข้าเมือง"),
        "dua_vehicle_stumbles" to DuaText("เมื่อรถสะดุด", "ในนามของอัลลอฮ.", "เมื่อพาหนะหรือยานพาหนะลื่นล้ม แทนที่จะพูดว่า 'ขอให้ชัยฏอนพินาศ'", "การกล่าวบิสมิลลาห์ทำให้ชัยฏอนหดตัวลงจนเหลือขนาดแมลงวัน"),
        "dua_ajz_kasal_haram" to DuaText("ที่ลี้ภัยจากความอ่อนแอและวัยชรา", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความสิ้นหวังและความเกียจคร้าน จากความขี้ขลาดและความชรา จากการทดสอบแห่งชีวิตและความตาย และจากการลงโทษในหลุมศพ", "Dua ที่หลบภัยที่ครอบคลุมทุกวัน", "ดุอาของท่านศาสดา ﷺ ทำบ่อยๆ"),
    )
}
